#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef long long ll;

typedef struct Edge {
    int to;
    int next;
    ll w;
} Edge;

typedef struct HeapNode {
    int v;
    ll d;
} HeapNode;

typedef struct MinHeap {
    HeapNode *a;
    int size;
    int cap;
} MinHeap;

static void heap_init(MinHeap *h, int cap) {
    h->a = (HeapNode *)malloc(sizeof(HeapNode) * (cap + 1));
    h->size = 0;
    h->cap = cap;
}

static void heap_push(MinHeap *h, int v, ll d) {
    if (h->size + 1 > h->cap) {
        h->cap *= 2;
        h->a = (HeapNode *)realloc(h->a, sizeof(HeapNode) * (h->cap + 1));
    }
    int i = ++h->size;
    while (i > 1 && h->a[i / 2].d > d) {
        h->a[i] = h->a[i / 2];
        i /= 2;
    }
    h->a[i].v = v;
    h->a[i].d = d;
}

static HeapNode heap_pop(MinHeap *h) {
    HeapNode ret = h->a[1];
    HeapNode last = h->a[h->size--];
    int i = 1;
    while (i * 2 <= h->size) {
        int c = i * 2;
        if (c + 1 <= h->size && h->a[c + 1].d < h->a[c].d) c++;
        if (h->a[c].d >= last.d) break;
        h->a[i] = h->a[c];
        i = c;
    }
    h->a[i] = last;
    return ret;
}

static int heap_empty(MinHeap *h) {
    return h->size == 0;
}

static void dijkstra(int n, int start, int *head, Edge *edges, ll *dist) {
    const ll INF = (1LL << 60);
    for (int i = 1; i <= n; i++) dist[i] = INF;
    dist[start] = 0;

    MinHeap h;
    heap_init(&h, n + 5);
    heap_push(&h, start, 0);

    while (!heap_empty(&h)) {
        HeapNode cur = heap_pop(&h);
        int v = cur.v;
        ll d = cur.d;
        if (d != dist[v]) continue;

        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            ll nd = d + edges[e].w;
            if (nd < dist[to]) {
                dist[to] = nd;
                heap_push(&h, to, nd);
            }
        }
    }

    free(h.a);
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    ll reward, pillarCost;
    int town, village;
    scanf("%lld %lld %d %d", &reward, &pillarCost, &town, &village);

    int *head = (int *)malloc(sizeof(int) * (N + 1));
    Edge *edges = (Edge *)malloc(sizeof(Edge) * (2 * M));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < M; i++) {
        int u, v;
        ll w;
        scanf("%d %d %lld", &u, &v, &w);

        edges[ecnt].to = v;
        edges[ecnt].w = w;
        edges[ecnt].next = head[u];
        head[u] = ecnt++;

        edges[ecnt].to = u;
        edges[ecnt].w = w;
        edges[ecnt].next = head[v];
        head[v] = ecnt++;
    }

    ll *dist = (ll *)malloc(sizeof(ll) * (N + 1));
    dijkstra(N, town, head, edges, dist);

    const ll INF = (1LL << 60);
    if (dist[village] >= INF / 2) {
        printf("-1\n");
    } else {
        ll ans = reward - pillarCost - 2LL * dist[village];
        printf("%lld\n", ans);
    }

    free(dist);
    free(edges);
    free(head);
    return 0;
}

