        auto [d, u] = pq.top();
        pq.pop();
        if (d != distFromVillage[u]) continue;
        for (auto [v, w] : adj[u]) {
            if (distFromVillage[v] > d + w) {
                distFromVillage[v] = d + w;
                pq.push({distFromVillage[v], v});
            }
        }
    }

    // For each node i, cost to go town->i->village is distFromTown[i] + distFromVillage[i]
    // Pillar cost at node i is L + (i+1)*K
    long long best = -INF;
    for (int i = 0; i < N; i++) {
        if (distFromTown[i] == INF || distFromVillage[i] == INF) continue;
        long long travelCost = distFromTown[i] + distFromVillage[i];
        long long pillarCost = L + (i + 1) * K;
        long long reward = -travelCost - pillarCost;
        best = max(best, reward);
    }

    // If no valid route, reward is 0? Problem says maximize, but if negative we might still output negative.
    // Typically if no path, carpenter cannot do job, reward = 0? But problem expects maximum possible.
    // However constraints guarantee at least one path? Not necessarily. We'll output best, which might be -INF.
    // But we can also consider not going at all: reward = 0 (no travel, no pillar cost, no reward from lord).
    // Lord gives money L? Actually lord's reward is money received minus cost. If no pillars, maybe reward 0.
    // The problem description: "The carpenter's reward is the money received from the lord minus the cost..."
    // If he doesn't go, he gets 0. So we compare with 0.
    best = max(best, 0LL);
    cout << best << "\n";

    return 0;
}

