import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int to, cost;
        Edge(int to, int cost) {
            this.to = to;
            this.cost = cost;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken()); // number of towns (including start and destination)
        int m = Integer.parseInt(st.nextToken()); // number of highways
        int start = 0; // town index 0
        int destination = n - 1; // mountain village index n-1

        // read pillar costs at each town (only destination matters for purchase)
        int[] pillarCost = new int[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            pillarCost[i] = Integer.parseInt(st.nextToken());
        }

        // build graph
        List<List<Edge>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            graph.get(a).add(new Edge(b, c));
            graph.get(b).add(new Edge(a, c));
        }

        // read lord's reward
        long reward = Long.parseLong(br.readLine());

        // Dijkstra from start to all nodes
        long[] distFromStart = dijkstra(graph, start, n);
        // Dijkstra from destination to all nodes
        long[] distToDestination = dijkstra(graph, destination, n);

        long maxProfit = Long.MIN_VALUE;
        // Try to buy pillars at each town (including start and destination)
        for (int town = 0; town < n; town++) {
            // Check reachability
            if (distFromStart[town] == Long.MAX_VALUE || distToDestination[town] == Long.MAX_VALUE) {
                continue;
            }
            // total travel cost = go from start to town, then from town to destination, then back from destination to start
            // But the problem says: go from town to mountain village and back, so we need round trip from start to destination via town.
            // Actually: start -> town (buy) -> destination -> start (return)
            // Travel cost = distFromStart[town] + distToDestination[town] + distFromStart[destination] (return)
            // But wait, return is from destination to start, that's just distFromStart[destination] (since graph undirected)
            long travelCost = distFromStart[town] + distToDestination[town] + distFromStart[destination];
            long totalCost = pillarCost[town] + travelCost;
            long profit = reward - totalCost;
            if (profit > maxProfit) {
                maxProfit = profit;
            }
        }

        // Output result
        System.out.println(maxProfit);
    }

    static long[] dijkstra(List<List<Edge>> graph, int source, int n) {
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[source] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[1]));
        pq.offer(new long[]{source, 0});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int u = (int) cur[0];
            long d = cur[1];
            if (d != dist[u]) continue;
            for (Edge e : graph.get(u)) {
                if (dist[e.to] > dist[u] + e.cost) {
                    dist[e.to] = dist[u] + e.cost;
                    pq.offer(new long[]{e.to, dist[e.to]});
                }
            }
        }
        return dist;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    static class Node implements Comparable<Node> {
        int v;
        long d;
        Node(int v, long d) {
            this.v = v;
            this.d = d;
        }
        public int compareTo(Node o) {
            return Long.compare(this.d, o.d);
        }
    }

    static final long INF = Long.MAX_VALUE / 4;

    static long[] dijkstra(List<Edge>[] graph, int start) {
        int n = graph.length;
        long[] dist = new long[n];
        Arrays.fill(dist, INF);
        PriorityQueue<Node> pq = new PriorityQueue<>();
        dist[start] = 0;
        pq.offer(new Node(start, 0));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.d != dist[cur.v]) continue;

            for (Edge e : graph[cur.v]) {
                long nd = cur.d + e.w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.offer(new Node(e.to, nd));
                }
            }
        }
        return dist;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();

        long[] reward = new long[n];
        for (int i = 0; i < n; i++) reward[i] = fs.nextLong();

        List<Edge>[] g = new ArrayList[n];
        List<Edge>[] rg = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
            rg[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            long c = fs.nextLong();
            g[u].add(new Edge(v, c));
            rg[v].add(new Edge(u, c));
        }

        int town = fs.nextInt() - 1;      // starting town
        int village = fs.nextInt() - 1;   // mountain village

        long[] fromTown = dijkstra(g, town);
        long[] toVillage = dijkstra(g, village);
        long[] fromVillage = dijkstra(rg, village);
        long[] toTown = dijkstra(rg, town);

        long ans = Long.MIN_VALUE;

        for (int i = 0; i < n; i++) {
            if (fromTown[i] >= INF || toVillage[i] >= INF || fromVillage[i] >= INF || toTown[i] >= INF) continue;
            long totalTravel = fromTown[i] + toVillage[i] + fromVillage[i] + toTown[i];
            long profit = reward[i] - totalTravel;
            ans = Math.max(ans, profit);
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
